// loader는 isomorphic — SSR 중엔 서버, 클라이언트 네비게이션엔 클라이언트
export const Route = createFileRoute('/products')({
  loader: async () => {
    const response = await fetch('/api/products')  // 양쪽 모두 실행 가능
    return response.json()
  },
})

// 서버 전용: createServerFn — RPC 패턴 (클라이언트에서 호출 → 네트워크 요청)
const updateUser = createServerFn({ method: 'POST' })
  .validator((data: UserData) => data)
  .handler(async ({ data }) => db.users.update(data))  // 서버에서만 실행

// 서버 전용: createServerOnlyFn — 클라이언트에서 호출하면 에러
const getEnvVar = createServerOnlyFn(() => process.env.DATABASE_URL)

// 클라이언트 전용
const saveToStorage = createClientOnlyFn((key, value) =>
  localStorage.setItem(key, JSON.stringify(value))
)

// 환경별 다른 구현
const getDeviceInfo = createIsomorphicFn()
  .server(() => ({ type: 'server', platform: process.platform }))
  .client(() => ({ type: 'client', userAgent: navigator.userAgent }))

