// Request Middleware — 모든 서버 요청에 적용 (.server만)
const loggingMiddleware = createMiddleware().server(async ({ next, request }) => {
  console.log('Request:', request.url)
  return next()
})

// Server Function Middleware — 서버 함수 전용 (.client + .server)
const authMiddleware = createMiddleware({ type: 'function' })
  .client(async ({ next }) => {
    return next({
      headers: { Authorization: `Bearer ${getToken()}` },  // 클라이언트에서 헤더 추가
    })
  })
  .server(async ({ next, context }) => {
    const user = await verifyToken(context.headers.Authorization)
    return next({ context: { user } })  // 서버에서 user를 context에 주입
  })

// 실행 순서 (의존성 우선)
// globalMiddleware1 → globalMiddleware2 → a → b → c → d → fn

// Global Middleware 등록 (src/start.ts)
export const startInstance = createStart(() => ({
  requestMiddleware: [csrfMiddleware],
  functionMiddleware: [loggingMiddleware],
}))

