function PostDetail() {
  const { post, commentsPromise } = Route.useLoaderData()
  const { postId } = Route.useParams()

  return (
    <article>
      <h1>{post.title}</h1>

      {/* 댓글 실패해도 게시글은 정상 표시 */}
      <CatchBoundary
        errorComponent={({ error, reset }) => (
          <div>
            <p>댓글 로딩 실패: {error.message}</p>
            {/* reset(): 에러 상태만 초기화, loader 재실행 안 함 */}
            <button onClick={reset}>재시도 (UI만)</button>
            {/* router.invalidate(): 캐시 무효화, loader 재실행 */}
            <button onClick={() => router.invalidate()}>재시도 (데이터 재요청)</button>
          </div>
        )}
        // postId 바뀌면 에러 상태 자동 초기화
        getResetKey={() => postId}
      >
        <Suspense fallback={<CommentsSkeleton />}>
          <Await promise={commentsPromise}>
            {(comments) => <CommentList comments={comments} />}
          </Await>
