import { stripSearchParams } from '@tanstack/react-router'
import { fallback, zodValidator } from '@tanstack/zod-adapter'

const defaultValues = {
  page: 1,
  status: 'all' as const,
  sort: 'date' as const,
}

export const Route = createFileRoute('/todos/')({
  validateSearch: zodValidator(z.object({
    page: fallback(z.number(), 1).default(1),
    status: fallback(z.enum(['all', 'completed', 'pending']), 'all').default('all'),
    sort: fallback(z.enum(['date', 'title']), 'date').default('date'),
  })),
  search: {
    middlewares: [stripSearchParams(defaultValues)],
  },
})

// URL 변화:
// /todos?page=1&status=all&sort=date  →  /todos
// /todos?page=2&status=all&sort=date  →  /todos?page=2
// /todos?page=1&status=completed      →  /todos?status=completed

// 커스텀 미들웨어 조합도 가능
search: {
  middlewares: [
    stripSearchParams(defaultValues),         // 기본값 제거
    ({ search, next }) => {                   // 빈 배열 제거
      const cleaned = { ...search }
      if (Array.isArray(cleaned.tags) && cleaned.tags.length === 0) {
        delete cleaned.tags
      }
      return next(cleaned)
    },
  ],
}

